class Solution:
    def daysUntilWarmer(self, temps: List[int]) -> List[int]:
        n = len(temps)
        wait = [0] * n
        for i in range(n):
            for j in range(i + 1, n):
                if temps[j] > temps[i]:
                    wait[i] = j - i
                    break
        return wait

