class Solution:
    def daysUntilWarmer(self, temps: List[int]) -> List[int]:
        n = len(temps)
        wait = [0] * n
        INF = n
        nxt = [INF] * 201
        for i in range(n - 1, -1, -1):
            first = INF
            for t in range(temps[i] + 101, 201):
                first = min(first, nxt[t])
            if first < INF:
                wait[i] = first - i
            nxt[temps[i] + 100] = i
        return wait

