class Solution {
    public int[] daysUntilWarmer(int[] temps) {
        int n = temps.length;
        int[] wait = new int[n], next = new int[201];
        Arrays.fill(next, n);
        for (int i = n - 1; i >= 0; i--) {
            int first = n;
            for (int t = temps[i] + 101; t < 201; t++) first = Math.min(first, next[t]);
            if (first < n) wait[i] = first - i;
            next[temps[i] + 100] = i;
        }
        return wait;
    }
}

