    vector<int> daysUntilWarmer(vector<int>& temps) {
        int n = temps.size();
        vector<int> wait(n, 0), stack;
        for (int i = 0; i < n; i++) {
            while (!stack.empty() && temps[stack.back()] < temps[i]) {
                wait[stack.back()] = i - stack.back();
                stack.pop_back();
            }
            stack.push_back(i);
        }
        return wait;
    }
};

