int* daysUntilWarmer(int* temps, int tempsSize, int* returnSize) {
    int n = tempsSize;
    int* wait = calloc(n, sizeof(int));
    int* stack = malloc(n * sizeof(int));
    int top = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && temps[stack[top - 1]] < temps[i]) {
            int j = stack[--top];
            wait[j] = i - j;
        }
        stack[top++] = i;
    }
    free(stack);
    *returnSize = n;
    return wait;
}
